step.instructions:
This step will execute an inline REXX script that accesses the variables:
- USER_NAME: ${instance-USER_NAME}
- DATASET_HLQ: ${instance-DATASET_HLQ}
- COUNTER: ${instance-COUNTER}

The REXX script will increment the counter and create a personalized message.

template.inlineTemplate:
/* REXX */ /* Inline REXX Example - Variable Access and Manipulation */ SAY '================================================' SAY 'REXX EXEC - Inline Execution' SAY '================================================' SAY ''
/* Access workflow variables using substitution */ user_name = '${instance-USER_NAME}' dataset_hlq = '${instance-DATASET_HLQ}' counter = '${instance-COUNTER}'
SAY 'Input Variables:' SAY ' USER_NAME = ' || user_name SAY ' DATASET_HLQ = ' || dataset_hlq SAY ' COUNTER = ' || counter SAY ''
/* Perform some operations */ new_counter = counter + 10 timestamp = DATE('S') || ' ' || TIME() message = 'Hello ' || user_name || '! Counter incremented to ' || new_counter
SAY 'Processing:' SAY ' New Counter = ' || new_counter SAY ' Timestamp = ' || timestamp SAY ' Message = ' || message SAY ''
/* Demonstrate REXX built-in functions */ SAY 'REXX Built-in Functions Demo:' SAY ' USERID() = ' || USERID() SAY ' MVSVAR(SYSNAME) = ' || MVSVAR('SYSNAME') SAY ' LENGTH(message) = ' || LENGTH(message) SAY ' WORDS(message) = ' || WORDS(message) SAY ''
/* Create output for workflow variable */ output_msg = 'REXX completed at ' || timestamp || ' - Counter=' || new_counter
SAY 'Output Variable:' SAY ' REXX_OUTPUT = ' || output_msg SAY '' SAY 'REXX execution completed successfully!' SAY '================================================' SAY 'WORKFLOW_STEP_SUCCESS'
EXIT 0

step.instructions:
This step executes a Unix shell script with these variables:
- USER_NAME: ${instance-USER_NAME}
- DATASET_HLQ: ${instance-DATASET_HLQ}
- COUNTER: ${instance-COUNTER}

REXX script demonstrating advanced variable manipulation with:
- USER_NAME: ${instance-USER_NAME}
- COUNTER: ${instance-COUNTER}

template.inlineTemplate:
/* REXX */ SAY '================================================' SAY 'REXX ADVANCED VARIABLE TECHNIQUES' SAY '================================================' SAY ''
/* Get variables */ user_name = '${instance-USER_NAME}' counter = '${instance-COUNTER}'
/* String manipulation */ SAY 'String Manipulation:' SAY ' Original name: ' || user_name SAY ' Uppercase: ' || TRANSLATE(user_name) SAY ' Lowercase: ' || TRANSLATE(user_name, , 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', , 'abcdefghijklmnopqrstuvwxyz') SAY ' Reversed: ' || REVERSE(user_name) SAY ' First char: ' || SUBSTR(user_name, 1, 1) SAY ''
/* Numeric operations */ SAY 'Numeric Operations:' SAY ' Counter: ' || counter SAY ' Counter * 2: ' || (counter * 2) SAY ' Counter ** 2: ' || (counter ** 2) SAY ' Counter / 2: ' || (counter / 2) SAY ' Counter // 3: ' || (counter // 3) SAY ''
/* Conditional logic */ SAY 'Conditional Logic:' IF counter > 10 THEN SAY ' Counter is greater than 10' ELSE SAY ' Counter is 10 or less'
IF LENGTH(user_name) > 5 THEN SAY ' Name is longer than 5 characters' ELSE SAY ' Name is 5 characters or shorter' SAY ''
/* Stem variables (arrays) */ SAY 'Stem Variables (Arrays):' data.0 = 3 data.1 = 'First item' data.2 = 'Second item' data.3 = 'Third item'
DO i = 1 TO data.0 SAY ' data.' || i || ' = ' || data.i END SAY ''
SAY 'Advanced REXX techniques demonstrated!' SAY '================================================' SAY 'WORKFLOW_STEP_SUCCESS'
EXIT 0
